 39 | export function canTravel(from, to, objects = OBJECTS) {
 40 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 41 |   for (let i = 0; i <= steps; i++) {
 42 |     const t = i / steps;
 43 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 44 |   }
 45 |   return true;
 46 | }
