 48 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 49 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 50 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 51 |   // Spiral outward in quarter-tile steps until we find a walkable point
 52 |   const step = 0.25;
 53 |   for (let r = step; r <= 3; r += step) {
 54 |     let best = null, bestDist = Infinity;
 55 |     const n = Math.ceil((r * 2) / step);
 56 |     for (let i = 0; i <= n; i++) {
 57 |       const t = i / n;
 58 |       for (const [cx, cy] of [
 59 |         [tx - r + t * r * 2, ty - r],
 60 |         [tx + r, ty - r + t * r * 2],
 61 |         [tx + r - t * r * 2, ty + r],
 62 |         [tx - r, ty + r - t * r * 2],
 63 |       ]) {
 64 |         const rx = Math.round(cx / step) * step;
 65 |         const ry = Math.round(cy / step) * step;
 66 |         if (!isWalkable(rx, ry, objects)) continue;
 67 |         const d = Math.hypot(rx - tx, ry - ty);
 68 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 69 |       }
 70 |     }
 71 |     if (best) return best;
 72 |   }
 73 |   return null;
 74 | }
