 37 | function ox(ctx,color,x,y,w,h,lw){
 38 |   ctx.strokeStyle=color; ctx.lineWidth=lw||1;
 39 |   ctx.strokeRect(Math.round(x)+0.5,Math.round(y)+0.5,Math.round(w)-1,Math.round(h)-1);
