 42 | export class OfficeRenderer {
 43 |   constructor(canvas){
 44 |     this.canvas=canvas; this.ctx=canvas.getContext('2d');
 45 |     this.width=0; this.height=0; this.zoom=1; this.scale=1;
 46 |     this.offset={x:0,y:0}; this.hits=[]; this._time=0;
 47 |     this.reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
 48 |     this.resize();
 49 |   }
 50 |   resize(){
 51 |     const b=this.canvas.getBoundingClientRect();
 52 |     this.width=b.width; this.height=b.height;
 53 |     const dpr=Math.min(window.devicePixelRatio||1,2);
 54 |     this.canvas.width=Math.round(b.width*dpr);
 55 |     this.canvas.height=Math.round(b.height*dpr);
 56 |     this.dpr=dpr; this.updateCamera();
 57 |   }
 58 |   updateCamera(){
 59 |     const rw=ROOM.width*TILE_SIZE, rh=ROOM.depth*TILE_SIZE;
 60 |     const raw=Math.min(this.width/rw,this.height/rh)*this.zoom;
 61 |     this.scale=Math.max(1,Math.floor(raw));
 62 |     this.offset={
 63 |       x:Math.round((this.width -rw*this.scale)/2),
 64 |       y:Math.round((this.height-rh*this.scale)/2),
 65 |     };
 66 |   }
 67 |   sp(tx,ty){
 68 |     const p=project(tx,ty);
 69 |     return{x:Math.round(p.x*this.scale+this.offset.x),
 70 |            y:Math.round(p.y*this.scale+this.offset.y)};
 71 |   }
 72 |   screenPoint(tx,ty,z=0){ return this.sp(tx,ty); }
 73 |   floorPoint(sx,sy){
 74 |     return unproject((sx-this.offset.x)/this.scale,(sy-this.offset.y)/this.scale);
 75 |   }
