 77 |   /* ── Floor: single flat color, no grid ──────────────────────────────── */
 78 |   floor(){
 79 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
 80 |     const tl=this.sp(0,0), W=ROOM.width*T, H=ROOM.depth*T;
 81 |     px(ctx,C.wallTop, tl.x, tl.y-T*1.5, W, T*1.5);
 82 |     px(ctx,C.wall,    tl.x, tl.y-T*3,   W, T*1.5);
 83 |     px(ctx,C.floorA,  tl.x, tl.y, W, H);
 84 |     px(ctx,C.skirting, tl.x-S*3, tl.y, S*3, H);
 85 |     px(ctx,C.skirting, tl.x, tl.y-S*3, W, S*3);
 86 |     ctx.strokeStyle='#181208'; ctx.lineWidth=Math.max(2,S*1.5);
 87 |     ctx.strokeRect(tl.x,tl.y,W,H);
 88 |   }
