 92 |     this.hits.push(obj);
 93 |     const hot=hovered===obj.id;
 94 |     const S=this.scale, T=TILE_SIZE*S;
 95 |     const p=this.sp(obj.x,obj.y), W=obj.w*T, H=obj.d*T, ctx=this.ctx;
 96 |     px(ctx,C.shadow, p.x+S*2, p.y+S*3, W, H);
