 98 |       case 'plant':     this._plant(ctx,p,W,H,S,T,hot); break;
 99 |       case 'board':     this._board(ctx,p,W,H,S,T,hot); break;
100 |       case 'cabinet':   this._cabinet(ctx,p,W,H,S,T,hot); break;
101 |       case 'shelf':     this._shelf(ctx,p,W,H,S,T,hot); break;
102 |       case 'desk':      this._desk(ctx,p,W,H,S,T,hot); break;
103 |       case 'desk-small':this._deskSmall(ctx,p,W,H,S,T,hot); break;
