467 |   /* ── Character: pixel-art top-down sprite ────────────────────────────── */
468 |   character(founder,dir,moving,time){
469 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
470 |     const p=this.sp(founder.x,founder.y);
471 |     const cx=Math.round(p.x+T/2), cy=Math.round(p.y+T/2);
472 | 
473 |     /* walk frame toggles every 180ms */
474 |     const frame=(moving&&!this.reducedMotion)?Math.floor(time/180)%2:0;
475 | 
476 |     /* dominant facing direction */
477 |     const facing=Math.abs(dir.x)>=Math.abs(dir.y)
478 |       ?(dir.x>0?'r':'l')
479 |       :(dir.y>0?'d':'u');
480 | 
481 |     /* helper: draw one "pixel" of the sprite, offset from character center */
482 |     const r=(color,dx,dy,w,h)=>
483 |       px(ctx,color,cx+Math.round(dx*S),cy+Math.round(dy*S),Math.round(w*S)||1,Math.round(h*S)||1);
484 | 
485 |     /* ── ground shadow ── */
486 |     ctx.globalAlpha=0.2; ctx.fillStyle='#000';
487 |     ctx.beginPath();
488 |     ctx.ellipse(cx,cy+Math.round(S*5.5),Math.round(S*4.5),Math.round(S*1.8),0,0,Math.PI*2);
489 |     ctx.fill(); ctx.globalAlpha=1;
490 | 
491 |     /* ── SHOES ── */
492 |     if(facing==='d'||facing==='r'||facing==='l'){
493 |       const f0=frame===0;
494 |       /* left foot forward or back */
495 |       r(C.shoe, -2.5, f0?5.0:4.2, 2.5, 1.6);
496 |       /* right foot opposite */
497 |       r(C.shoe,  0.5, f0?4.2:5.0, 2.5, 1.6);
498 |     } else {
499 |       /* facing up – backs of feet visible */
500 |       r(C.shoe, -2.5, 4.5, 2.2, 1.5);
501 |       r(C.shoe,  0.8, frame===0?4.5:4.0, 2.2, 1.5);
502 |     }
503 | 
504 |     /* ── LEGS ── */
505 |     if(facing==='u'){
506 |       r(C.pantsD, -2.5, 1.5, 2.2, 3.2);
507 |       r(C.pantsD,  0.8, 1.5, 2.2, 3.2);
508 |     } else {
509 |       const f0=frame===0;
510 |       r(C.pants,  -2.5, f0?1.5:2.2, 2.2, f0?3.5:2.8);
511 |       r(C.pants,   0.8, f0?2.2:1.5, 2.2, f0?2.8:3.5);
512 |       /* pant crease highlight */
513 |       r('rgba(255,255,255,0.12)', -2.2, 1.8, 0.8, 2.5);
514 |       r('rgba(255,255,255,0.12)',  1.1, 1.8, 0.8, 2.5);
515 |     }
516 | 
517 |     /* ── BODY / SHIRT ── */
518 |     /* shirt shadow */
519 |     r(C.shirtD, -2.8, -4.5, 6.2, 6.8);
520 |     /* shirt main */
521 |     r(C.shirt, -3.0, -5.0, 6.2, 6.8);
522 |     /* shirt highlight top edge */
523 |     r('rgba(255,255,255,0.18)', -2.5, -5.0, 5.2, 1.5);
524 |     /* collar */
525 |     r(C.skin, -1.0, -5.2, 2.5, 1.8);
526 | 
527 |     /* ── ARMS ── */
528 |     const armOff=(moving&&!this.reducedMotion)?(frame===0?0.8:-0.8):0;
529 |     if(facing!=='u'){
530 |       /* left arm + hand */
531 |       r(C.shirt,  -5.2, -4.2+armOff,  2.2, 4.8);
532 |       r(C.skin,   -5.2,  0.8+armOff,  2.2, 2.0);
533 |       /* right arm + hand */
534 |       r(C.shirt,   3.2, -4.2-armOff,  2.2, 4.8);
535 |       r(C.skin,    3.2,  0.8-armOff,  2.2, 2.0);
536 |     } else {
537 |       r(C.shirt, -5.2, -4.2, 2.2, 4.5);
538 |       r(C.shirt,  3.2, -4.2, 2.2, 4.5);
539 |     }
540 | 
541 |     /* ── NECK ── */
542 |     r(C.skin, -1.0, -5.8, 2.5, 1.5);
543 | 
544 |     /* ── HEAD SHADOW ── */
545 |     r(C.skinD, -3.8, -14.5, 8.2, 9.5);
546 | 
547 |     /* ── HEAD ── */
548 |     r(C.skin, -4.0, -15.0, 8.2, 9.5);
549 | 
550 |     /* ── HAIR ── */
551 |     r(C.hair, -4.0, -15.0, 8.2, 3.0); /* top band */
552 |     if(facing!=='r') r(C.hair, -4.0, -15.0, 1.5, 9.5); /* left side */
553 |     if(facing!=='l') r(C.hair,  2.8, -15.0, 1.5, 9.5); /* right side */
554 |     /* hair shine */
555 |     r('rgba(255,255,255,0.14)', -2.5, -15.0, 3.5, 1.5);
556 | 
557 |     /* ── FACE (only when not facing up) ── */
558 |     if(facing!=='u'){
559 |       /* compute eye positions per facing */
560 |       const eyeLX=facing==='r'?-0.5:(facing==='l'?-2.2:-2.0);
561 |       const eyeRX=facing==='r'? 1.8:(facing==='l'?-0.2: 1.2);
562 |       const eyeY=-9.5;
563 |       /* eye whites */
564 |       r(C.eyeW, eyeLX-0.3, eyeY,     2.8, 2.2);
565 |       r(C.eyeW, eyeRX-0.3, eyeY,     2.8, 2.2);
566 |       /* pupils */
567 |       r(C.eye,  eyeLX+0.2, eyeY+0.5, 1.8, 1.5);
568 |       r(C.eye,  eyeRX+0.2, eyeY+0.5, 1.8, 1.5);
569 |       /* eye shines */
570 |       r('rgba(255,255,255,0.9)', eyeLX+1.0, eyeY+0.3, 0.9, 0.9);
571 |       r('rgba(255,255,255,0.9)', eyeRX+1.0, eyeY+0.3, 0.9, 0.9);
572 |       /* nose */
573 |       r(C.skinD, 0.0, -7.8, 1.2, 1.2);
574 |       /* mouth */
575 |       r(C.skinD, -1.5, -6.0, 3.8, 1.0);
576 |       /* smile corners */
577 |       if(facing==='d'){
578 |         r(C.skinD, -1.5, -6.5, 0.8, 0.8);
579 |         r(C.skinD,  2.0, -6.5, 0.8, 0.8);
580 |       }
581 |     } else {
582 |       /* facing up – show back of head (no face), just ears */
583 |       r(C.skin, -5.0, -12.0, 1.2, 2.5);
584 |       r(C.skin,  4.2, -12.0, 1.2, 2.5);
585 |     }
586 | 
587 |     /* ── NAME TAG ── */
588 |     ctx.save();
589 |     const tagY=cy+Math.round(S*(-19));
590 |     ctx.font='bold '+Math.max(7,Math.round(S*5))+'px "Courier New",monospace';
591 |     ctx.textAlign='center'; ctx.textBaseline='middle';
592 |     const tw=Math.round(ctx.measureText('ALEX').width+S*6), th=Math.round(S*7);
593 |     px(ctx,'rgba(8,12,18,0.85)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th);
594 |     ox(ctx,'rgba(100,180,255,0.65)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th, 1);
595 |     ctx.fillStyle='#a8d8ff'; ctx.fillText('ALEX',cx,tagY);
596 |     ctx.restore();
597 |   }
