600 |   /* ── Destination marker: single blinking tile (no dashed line) ───────── */
601 |   drawDestMarker(pathArr,time){
602 |     if(!pathArr.length) return;
603 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
604 |     const last=pathArr[pathArr.length-1];
605 |     const lp=this.sp(Math.floor(last.x),Math.floor(last.y));
606 |     /* blink between 0.25 and 0.75 opacity */
607 |     const blink=this.reducedMotion?0.6:0.25+Math.sin(time/200)*0.38;
608 |     ctx.globalAlpha=blink;
609 |     px(ctx,C.dest, lp.x, lp.y, T, T);
610 |     ctx.globalAlpha=1;
611 |     /* crisp 1-tile border */
612 |     ox(ctx,C.destRing, lp.x, lp.y, T, T, Math.max(2,S));
613 |     /* small footprint dots inside to make it feel like a marker */
614 |     const fw=Math.round(S*2.5), fh=Math.round(S*2);
615 |     px(ctx,'rgba(255,240,80,0.7)', Math.round(lp.x+T/2-fw/2-S*2), Math.round(lp.y+T/2-fh/2+S), fw, fh);
616 |     px(ctx,'rgba(255,240,80,0.7)', Math.round(lp.x+T/2-fw/2+S*2), Math.round(lp.y+T/2-fh/2-S), fw, fh);
617 |   }
