619 |   /* ── Main render ─────────────────────────────────────────────────────── */
620 |   render({founder,path,hovered,hoverFloor,direction,moving,time}){
621 |     const ctx=this.ctx;
622 |     this._time=time;
623 |     ctx.imageSmoothingEnabled=false;
624 |     ctx.setTransform(this.dpr,0,0,this.dpr,0,0);
625 |     px(ctx,'#18120c',0,0,this.width,this.height);
626 |     this.floor();
627 | 
628 |     /* destination tile blink */
629 |     this.drawDestMarker(path,time);
630 | 
631 |     /* depth sort objects + player, draw back-to-front */
632 |     this.hits=[];
633 |     const entries=OBJECTS.map(o=>({o,depth:o.y+o.d}));
634 |     entries.push({player:true,depth:founder.y+1});
635 |     entries.sort((a,b)=>a.depth-b.depth);
636 |     for(const entry of entries){
637 |       if(entry.player) this.character(founder,direction,moving,time);
638 |       else this.drawObject(entry.o,hovered);
639 |     }
640 |   }
641 | 
642 |   hitTest(sx,sy){
643 |     const wp=this.floorPoint(sx,sy);
644 |     for(const o of[...this.hits].reverse()){
645 |       if(wp.x>=o.x&&wp.x<o.x+o.w&&wp.y>=o.y&&wp.y<o.y+o.d) return o;
646 |     }
647 |     return null;
648 |   }
649 | }
