function tick(dt) {
  let moving = false;
  const before = { ...state.founder };

  // ── Vault / jump arc ────────────────────────────────────────────────────
  if (vaultCooldown > 0) vaultCooldown = Math.max(0, vaultCooldown - dt);
  if (jumpState) {
    jumpState.t += dt / jumpState.duration;
    if (jumpState.t >= 1) {
      // Land
      jumpState.t = 1;
      state.founder.x = jumpState.toX;
      state.founder.y = jumpState.toY;
      if (jumpState.vaultObject) {
        complete('parkour');
        playSound('complete');
        toast('🤸 Vaulted! Nice moves. −2 stamina, +1 style point.');
      }
      vaultCooldown = 0.3;
      jumpState = null;
    } else {
      // Interpolate position along arc
      const t = jumpState.t;
      state.founder.x = jumpState.fromX + (jumpState.toX - jumpState.fromX) * t;
      state.founder.y = jumpState.fromY + (jumpState.toY - jumpState.fromY) * t;
    }
    moving = true;
  } else if (keys.size) {
    // ── Sprint modifier ────────────────────────────────────────────────────
    const isSprinting = sprinting && state.energy > 1;
    const currentSpeed = isSprinting ? speed * 1.95 : speed;

    const sx = Number(keys.has('d') || keys.has('arrowright')) - Number(keys.has('a') || keys.has('arrowleft'));
    const sy = Number(keys.has('s') || keys.has('arrowdown')) - Number(keys.has('w') || keys.has('arrowup'));
    const dx = sx + sy, dy = sy - sx;
    const length = Math.hypot(dx, dy);
    if (length) {
      direction = { x: dx / length, y: dy / length };
      const candidate = { x: state.founder.x + direction.x * currentSpeed * dt, y: state.founder.y + direction.y * currentSpeed * dt };
      if (canTravel(state.founder, candidate)) state.founder = candidate;
      else {
        const xOnly = { x: candidate.x, y: state.founder.y };
        const yOnly = { x: state.founder.x, y: candidate.y };
        if(canTravel(state.founder,xOnly))state.founder=xOnly;
        else if(canTravel(state.founder,yOnly))state.founder=yOnly;
      }
      // Sprint stamina drain: 1 extra HP every 0.7 seconds
      if (isSprinting) {
        sprintDrainAccumulator += dt;
        if (sprintDrainAccumulator >= 0.7) {
          sprintDrainAccumulator %= 0.7;
          changeEnergy(-1);
          if (state.energy <= 0) { burnOut(); return moving; }
        }
        // Dash trail: record ghost positions every 3 frames (~50ms)
        if (dashTrail.length === 0 || Math.hypot(state.founder.x - dashTrail[dashTrail.length-1].x, state.founder.y - dashTrail[dashTrail.length-1].y) > 0.18) {
          dashTrail.push({ x: state.founder.x, y: state.founder.y, alpha: 0.55 });
          if (dashTrail.length > 5) dashTrail.shift();
        }
      }
    }
  } else if (path.length) {
    sprinting = false;
    let remaining = speed * dt;
    while (path.length && remaining > 0) {
      const target = path[0];
      const dx = target.x - state.founder.x, dy = target.y - state.founder.y;
      const distance = Math.hypot(dx, dy);
      if (distance > .001) direction = { x: dx / distance, y: dy / distance };
      if (distance <= remaining) { state.founder = { ...target };remaining -= distance;path.shift(); }
      else { state.founder.x += direction.x * remaining;state.founder.y += direction.y * remaining;remaining = 0; }
    }
    if (!path.length) {
      const object = pendingInteraction;pendingInteraction = null;save();updateUI();
      if (object) openInteraction(object);
    }
  }

  // Fade out dash trail when not sprinting
  if (!sprinting || keys.size === 0) {
    for (const ghost of dashTrail) ghost.alpha -= dt * 3.5;
    dashTrail = dashTrail.filter(g => g.alpha > 0);
  }

  const distance = Math.hypot(state.founder.x - before.x, state.founder.y - before.y);
  moving = moving || distance > .00001;
  state.distance += distance;
  if (state.distance >= 1.2) complete('walk');
  if (moving) $('#founder-hint').style.opacity = '0';
  clockAccumulator += dt;
  saveAccumulator += dt;
  energyDrainAccumulator += dt;
  if (clockAccumulator >= 3) { state.minutes = Math.min(1079, state.minutes + 1);clockAccumulator %= 3;updateUI(); }
  if (saveAccumulator >= 2) { saveAccumulator %= 2;save(); }
  // Drain 1 energy per drainInterval real-seconds (coffee speeds this up; sleep stops it)
  if (energyDrainAccumulator >= drainInterval) {
    energyDrainAccumulator %= drainInterval;
    if (!state.completed.includes('sleep')) {
      changeEnergy(-1);
      updateUI();
      if (state.energy <= 20 && !lowEnergyWarned) {
        lowEnergyWarned = true;
        toast('⚠️ Running low on stamina. Grab a coffee — or finish your tasks and sleep!');
      }
      if (state.energy <= 0) { burnOut(); return moving; }
    }
  }
  return moving;
}

// Compute current jump height (0 = on ground) for the renderer
function currentJumpHeight() {
  if (!jumpState) return 0;
  // Parabolic arc: h = 4 * peak * t * (1 - t)
  return jumpState.peakHeight * 4 * jumpState.t * (1 - jumpState.t);
}

function frame(time) {
  const dt = lastTime ? Math.min((time - lastTime) / 1000, .05) : 0;
  lastTime = time;
  let moving = false;
  if (!paused && !dialog.open && !document.hidden) { visualTime += dt * 1000; moving = tick(dt); }
  renderer.render({ founder: state.founder, path, hovered, hoverFloor, direction, moving, time: visualTime, jumpHeight: currentJumpHeight(), sprinting: sprinting && keys.size > 0, dashTrail });
  requestAnimationFrame(frame);
}

