function visit(id) {
  if (id === 'walk') {
    goTo({ x: 3.2, y: 7.8 });
    return;
  }
  if (id === 'parkour') {
    if (state.completed.includes('parkour')) { toast('🤸 Already nailed it. Show-off.'); return; }
    toast('🤸 Hold Shift to sprint · Press Space while moving to vault over furniture!');
    goTo({ x: 12.5, y: 4.5 }); // near the chair/pills — good vaulting territory
    return;
  }
  const o = id === 'coffee' ? OBJECTS.find(o => o.id === 'cabinet')
          : id === 'sleep'  ? OBJECTS.find(o => o.id === 'bed')
          : OBJECTS.find(o => o.id === id);
  if (o) goTo(o.target, o);
}

