 31 | export function isWalkable(x, y, objects = OBJECTS) {
 32 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 33 |   const r = FOUNDER_RADIUS;
 34 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 35 |   const pad = 0.05;
 36 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 37 | }
