  const objCx = target.x + target.w / 2;
  const objCy = target.y + target.d / 2;
  const halfExtent = Math.abs(direction.x) > Math.abs(direction.y)
    ? target.w / 2
    : target.d / 2;
  const landX = objCx + direction.x * (halfExtent + 0.65);
  const landY = objCy + direction.y * (halfExtent + 0.65);
  // Check landing spot is walkable
  if (!isWalkable(landX, landY)) { toast('Nowhere to land! Clear a path first.'); return; }
