 36 | export function isWalkable(x, y, objects = OBJECTS) {
 37 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 38 |   const r = FOUNDER_RADIUS;
 39 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 40 |   const pad = 0.05;
 41 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 42 | }
