 44 | export function canTravel(from, to, objects = OBJECTS) {
 45 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 46 |   for (let i = 0; i <= steps; i++) {
 47 |     const t = i / steps;
 48 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 49 |   }
 50 |   return true;
 51 | }
