 53 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 54 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 55 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 56 |   // Spiral outward in quarter-tile steps until we find a walkable point
 57 |   const step = 0.25;
 58 |   for (let r = step; r <= 3; r += step) {
 59 |     let best = null, bestDist = Infinity;
 60 |     const n = Math.ceil((r * 2) / step);
 61 |     for (let i = 0; i <= n; i++) {
 62 |       const t = i / n;
 63 |       for (const [cx, cy] of [
 64 |         [tx - r + t * r * 2, ty - r],
 65 |         [tx + r, ty - r + t * r * 2],
 66 |         [tx + r - t * r * 2, ty + r],
 67 |         [tx - r, ty + r - t * r * 2],
 68 |       ]) {
 69 |         const rx = Math.round(cx / step) * step;
 70 |         const ry = Math.round(cy / step) * step;
 71 |         if (!isWalkable(rx, ry, objects)) continue;
 72 |         const d = Math.hypot(rx - tx, ry - ty);
 73 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 74 |       }
 75 |     }
 76 |     if (best) return best;
 77 |   }
 78 |   return null;
 79 | }
