/* ── Dash button — standalone physical button ─────────────────────────── */
#dash-button{
  position:fixed;bottom:160px;right:12px;
  width:64px;height:64px;
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  background:rgba(14,22,14,.96);
  border:3px solid #3a5a2a;
  border-bottom-width:5px;
  border-radius:10px;
  color:#78c878;
  font-family:inherit;
  cursor:pointer;
  z-index:110;
  overflow:hidden;
  box-shadow:0 4px 0 #1a2a10, 0 6px 16px rgba(0,0,0,.55);
  transition:background .1s,border-color .1s,box-shadow .08s,transform .08s;
  -webkit-tap-highlight-color:transparent;
  touch-action:manipulation;
}
#dash-button:hover{background:rgba(24,40,18,.98);border-color:#5a8a3a}
#dash-button:active{transform:translateY(2px);box-shadow:0 2px 0 #1a2a10,0 4px 10px rgba(0,0,0,.55)}
#dash-button .dash-btn-icon{font-size:22px;line-height:1;display:block;transition:transform .1s}
#dash-button .dash-btn-label{font-size:9px;letter-spacing:2px;font-weight:700;line-height:1;color:#a8d888}
#dash-button .dash-btn-key{font-size:6px;letter-spacing:.5px;color:#4a6a3a;line-height:1;font-family:inherit}
/* Active / locked-on state */
#dash-button[aria-pressed=true]{
  background:rgba(30,65,10,.98);
  border-color:#78c838;
  color:#c8f070;
  box-shadow:0 4px 0 #2a5010, 0 0 20px #78c83866, inset 0 0 12px rgba(120,200,56,.12);
}
#dash-button[aria-pressed=true] .dash-btn-icon{
  animation:dash-icon-pulse .5s ease-in-out infinite alternate;
}
#dash-button[aria-pressed=true] .dash-btn-label{color:#c8f070}
#dash-button[aria-pressed=true] .dash-btn-key{color:#78a848}
#dash-button[aria-pressed=true]::before{
  content:'';position:absolute;inset:0;
  background:linear-gradient(135deg,rgba(120,200,56,.15) 0%,transparent 55%);
  animation:dash-shimmer .7s linear infinite;
  pointer-events:none;
}
#dash-button:disabled{opacity:.35;pointer-events:none}
@keyframes dash-shimmer{0%{transform:translateX(-110%) skewX(-12deg)}100%{transform:translateX(220%) skewX(-12deg)}}
@keyframes dash-icon-pulse{from{transform:scale(1)}to{transform:scale(1.18) translateY(-1px)}}

