// ── Parkour: blink dash — instant short-range teleport forward ───────────
function tryBlink() {
  if (blinkCooldown > 0) { toast('⚡ Blink recharging…'); return; }
  if (state.energy < 8) { toast('Too drained to blink. Grab a coffee first. ☕'); return; }
  if (paused || dialog.open) return;

  // Step forward in direction as far as walkable, up to BLINK_DIST tiles
  const BLINK_DIST = 3.0;
  const STEPS = 24; // resolution of the walk-forward check
  let landX = state.founder.x;
  let landY = state.founder.y;
  for (let i = 1; i <= STEPS; i++) {
    const t = (i / STEPS) * BLINK_DIST;
    const cx = state.founder.x + direction.x * t;
    const cy = state.founder.y + direction.y * t;
    if (!isWalkable(cx, cy)) break;
    landX = cx;
    landY = cy;
  }

  const dist = Math.hypot(landX - state.founder.x, landY - state.founder.y);
  if (dist < 0.25) { toast('Nowhere to blink — something is blocking the way.'); return; }

  // Stamp a dense burst of ghost positions from current pos to landing pos
  for (let i = 0; i <= 6; i++) {
    const t = i / 6;
    dashTrail.push({
      x: state.founder.x + (landX - state.founder.x) * t,
      y: state.founder.y + (landY - state.founder.y) * t,
      alpha: 0.7 - t * 0.5,
    });
  }
  if (dashTrail.length > 12) dashTrail.splice(0, dashTrail.length - 12);

  // Teleport
  state.founder.x = landX;
  state.founder.y = landY;
  changeEnergy(-8);
  blinkCooldown = 1.2;
  complete('parkour');
  updateUI();
}

