// ── Parkour: attempt to vault over a nearby vaultable object ──────────────
function tryVault() {
  if (jumpState || vaultCooldown > 0) return; // already airborne or cooling down
  if (state.energy < 6) { toast('Too drained to jump. Grab a coffee first. ☕'); return; }
  const isSprintJump = (sprinting || dashLocked) && state.energy > 1;
  // Sprint-jump carries further: scale reach and landing distance
  const sprintMult = isSprintJump ? 1.6 : 1.0;
  // Look for a vaultable object in the direction of movement, within reach
  const reach = 2.0 * sprintMult;
  const fx = state.founder.x + direction.x * reach;
  const fy = state.founder.y + direction.y * reach;
  const target = OBJECTS.find(o =>
    VAULTABLE_TYPES.has(o.type) &&
    fx > o.x - 0.4 && fx < o.x + o.w + 0.4 &&
    fy > o.y - 0.4 && fy < o.y + o.d + 0.4
  );
  if (!target) {
    // No object nearby — do a free hop: costs stamina and lands with a stumble
    const hopDist = 1.0 * sprintMult;
    const toX = state.founder.x + direction.x * hopDist;
    const toY = state.founder.y + direction.y * hopDist;
    changeEnergy(-4);
    jumpState = { t: 0, duration: 0.28, fromX: state.founder.x, fromY: state.founder.y, toX, toY, peakHeight: 1.8 + (isSprintJump ? 0.6 : 0), vaultObject: null, freeHop: true, sprintJump: isSprintJump };
    return;
  }
  // Land on the other side: project from object center along movement direction
  const objCx = target.x + target.w / 2;
  const objCy = target.y + target.d / 2;
  const halfExtent = Math.abs(direction.x) > Math.abs(direction.y)
    ? target.w / 2
    : target.d / 2;
  const landDist = (halfExtent + 0.65) * sprintMult;
  const landX = objCx + direction.x * landDist;
  const landY = objCy + direction.y * landDist;
  // Check landing spot is walkable
  if (!isWalkable(landX, landY)) { toast('Nowhere to land! Clear a path first.'); return; }
  // Scale jump height and duration with table span
  const tableSpan = Math.max(target.w, target.d);
  const peakH = (2.5 + tableSpan * 0.5) * (isSprintJump ? 1.25 : 1);
  const dur = (0.30 + tableSpan * 0.06) * (isSprintJump ? 0.8 : 1); // sprint-jump is snappier
  const isShortcutTable = target.type === 'table-vault';
  changeEnergy(isShortcutTable ? -6 : -10);
  jumpState = { t: 0, duration: dur, fromX: state.founder.x, fromY: state.founder.y, toX: landX, toY: landY, peakHeight: peakH, vaultObject: target, sprintJump: isSprintJump };
  playSound('coffee');
}

